    const NAMEPLATE_CONFIG = { offsetY: -65 };

    // 1. Спрайты для КЛАССОВ и ФОРМ (Вложенная структура)
    // Ищи по слову ЛЕГИОНЕР, ЛУЧНИК и т.д. и меняй на свой base64
